import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>WebP'yi PNG'ye dönüştürmek birkaç dakikalık bir iştir. Program kurmazsınız, dosyanız cihazınızdan ayrılmaz ve sonunda her programda açılan bir PNG indirirsiniz.</p>\n<p>Bu yazı, işlemi beş adımda anlatıyor. İster tek bir logo ister bütün bir klasör dönüştürün, adımlar aynıdır.</p>\n<p>Sonunda saydamlığı nasıl doğrulayacağınızı, toplu dönüştürmeyi ve yaygın sorunları nasıl çözeceğinizi de öğreneceksiniz.</p>\n<h2 id=\"before-you-start\">Başlamadan önce: neden dönüştürdüğünüzü bilin</h2>\n<p>Önce hedefi belirleyin: düzenleme mi, baskı mı, form mu, sunum mu? Hedef, dönüştürmenin gerekli olup olmadığını söyler.</p>\n<p>Web'de kalacak bir görseli dönüştürmeyin. WebP web içindir; yalnızca dosya tarayıcı dışına çıkacaksa PNG'ye çevirin.</p>\n<p>Orijinal WebP'lerin bir yedeğini alın. PNG büyüdüğü için arşivde WebP'yi saklamak daha akıllıcadır.</p>\n<h2 id=\"step-1-open-tool\">Adım 1: WebP'den PNG'ye aracını açın</h2>\n<p>Tarayıcınızda WebP'den PNG'ye aracını açın. Sayfa hemen yüklenir; hesap açmanız ya da program kurmanız gerekmez.</p>\n<p>Araç bütünüyle tarayıcıda işler. Dosyalarınız sunucuya gitmez; gizli ve müşteri dosyalarını güvenle çevirebilirsiniz.</p>\n<h2 id=\"step-2-upload\">Adım 2: WebP dosyalarınızı yükleyin</h2>\n<p>Dosyaları yükleme alanına sürükleyin ya da dosya seçiciyle seçin. Birden fazla WebP'yi aynı anda seçebilirsiniz.</p>\n<p>Eklenen dosyalar listede görünür; adı ve boyutu yazılır. Yanlış dosyayı listeden çıkarabilirsiniz.</p>\n<h2 id=\"step-3-convert\">Adım 3: dosyaları dönüştürün</h2>\n<p>Dönüştür düğmesine tıklayın. Araç dosyaları sırayla işler; ilerleme çubuğu durumu gösterir.</p>\n<p>Dönüştürme genellikle birkaç saniye sürer. Kalite ayarı yoktur; PNG her zaman kayıpsız üretilir.</p>\n<h2 id=\"step-4-confirm-transparency\">Adım 4: saydamlığın korunduğunu doğrulayın</h2>\n<p>Dönüştürme bitince önizlemeyi açın. Saydam alanlar damalı desenle görünür; logonun köşeleri temiz olmalıdır.</p>\n<p>Karşılaştırma görünümüyle orijinali ve PNG'yi yan yana inceleyin. Kenarlarda beyaz hale görürseniz kaynak WebP'nin gerçekten saydam olduğundan emin olun.</p>\n<h2 id=\"step-5-download\">Adım 5: PNG dosyalarını indirin</h2>\n<p>Her dosyayı tek tek indirebilir ya da tamamını ZIP olarak alabilirsiniz. ZIP, toplu dönüştürmelerde çok pratiktir.</p>\n<p>İndirilen dosyaların adlarını kontrol edin. Orijinal ad korunur, yalnızca uzantı .png olur.</p>\n<ol>\n<li>WebP'den PNG'ye aracını açın ve WebP dosyalarınızı yükleyin.</li>\n<li>Dönüştür düğmesine basın; kalite ayarı gerekmez.</li>\n<li>Saydamlığı önizlemede doğrulayın.</li>\n<li>PNG dosyalarını tek tek ya da ZIP olarak indirin.</li>\n</ol>\n<h2 id=\"converting-a-batch\">Bir grup WebP görselini dönüştürmek</h2>\n<p>Bir siteden indirdiğiniz onlarca WebP'yi tek seferde yükleyin. Araç hepsini sırayla işler.</p>\n<p>Toplu dönüştürmede dosya adları aynı kalır; yalnızca uzantı değişir. Klasör düzeniniz bozulmaz.</p>\n<p>Sonuçları tek ZIP dosyası olarak indirin. Tek indirme, onlarca dosyayı düzenli alır.</p>\n<h2 id=\"using-png-for-editing\">PNG'yi düzenlemek için kullanmak</h2>\n<p>Birçok düzenleme programı WebP açamaz. Düzenlemeden önce PNG'ye çevirmek, programın dosyayı sorunsuz açmasını sağlar.</p>\n<p>Düzenleme bitince dosyayı istediğiniz formatta kaydedin. Web için WebP, baskı için PNG ya da JPG kullanabilirsiniz.</p>\n<p>Orijinal WebP'yi saklayın. Düzenlenmiş sürüm ayrı bir dosyadır; orijinal ileride yeniden başlamak için gerekir.</p>\n<h2 id=\"fixing-problems\">Yaygın sorunları çözmek</h2>\n<p>Dosya yüklenmiyorsa boyut sınırını kontrol edin. Araç 20 MB'a kadar dosya kabul eder; daha büyük dosyaları önce sıkıştırın.</p>\n<p>Uzantısı olmayan bir WebP dosyası yüklenmiyorsa dosya adının sonuna .webp ekleyin. Araç, formatı uzantıdan tanır.</p>\n<p>Dönüştürülen PNG beklenenden büyükse şaşırmayın. PNG kayıpsızdır ve WebP'den her zaman daha büyük olur; bu normaldir.</p>\n<h2 id=\"mobile-tips\">Telefon ve tablet ipuçları</h2>\n<p>Modern mobil tarayıcılar aracı tam olarak destekler. Telefonda dosya seçip dönüştürebilir ve sonucu indirebilirsiniz.</p>\n<p>Telefonda indirilen dosyalar genellikle İndirilenler klasörüne gider. Dosyayı bulamazsanız tarayıcının indirme listesine bakın.</p>\n<p>Çok sayıda dosyayı dönüştürmek bilgisayarda daha rahat olur. Toplu işler için masaüstünü tercih edin.</p>\n<h2 id=\"webp-for-photoshop\">Photoshop için WebP dönüştürmek</h2>\n<p>Photoshop'un yeni sürümleri WebP açar ama eski sürümler açamaz. Emin değilseniz önce PNG'ye dönüştürün.</p>\n<p>PNG'yi Photoshop'ta açın ve katman olarak kullanın. Saydamlık korunduğu için logo her arka plan üzerinde temiz görünür.</p>\n<p>Çalışmayı kaydederken PSD kullanın. PNG, teslim formatıdır; çalışma dosyası PSD olmalıdır.</p>\n<h2 id=\"webp-for-powerpoint\">PowerPoint için WebP dönüştürmek</h2>\n<p>PowerPoint'in yeni sürümleri WebP destekler ama eski sürümler desteklemez. Sunum paylaşılacaksa PNG kullanın.</p>\n<p>PNG'yi slayda sürükleyip bırakın. Görsel her bilgisayarda aynı görünür; sunum günü sürpriz yaşanmaz.</p>\n<p>Sunumdan önce dosyaları çevrimdışı deneyin. Salon bilgisayarında görselin açıldığından emin olun.</p>\n<h2 id=\"webp-for-print-shop\">Baskı merkezi için WebP dönüştürmek</h2>\n<p>Baskı merkezleri WebP kabul etmez. Baskıya göndermeden önce PNG'ye çevirin ve çözünürlüğü kontrol edin.</p>\n<p>Baskıda çözünürlük çok önemlidir. Web'den indirilen küçük görsel baskıda bulanık çıkar; 300 DPI hedefleyin.</p>\n<p>Baskı merkezine hangi formatı istediklerini sorun. Doğru format ve çözünürlük, boşa giden baskıyı önler.</p>\n<h2 id=\"webp-for-form\">Form için WebP dönüştürmek</h2>\n<p>Formlar ve portallar genellikle yalnızca JPG ve PNG kabul eder. Yüklemeden önce WebP'yi PNG'ye çevirin.</p>\n<p>Formun boyut sınırını kontrol edin. PNG büyükse önce boyutunu küçültün ya da JPG'ye dönüştürün.</p>\n<p>Yüklemeden önce dosyayı açıp kontrol edin. Doğru görseli yüklediğinizden emin olun; yanlış dosya başvuruyu geciktirir.</p>\n<h2 id=\"webp-from-chat\">Sohbetten alınan WebP'yi dönüştürmek</h2>\n<p>Mesajlaşma uygulamaları görselleri bazen WebP olarak kaydeder. Telefonunuza inen görsel WebP olabilir.</p>\n<p>Bu dosyayı PNG'ye çevirmek basittir. Aracı telefonda açın, dosyayı seçin ve dönüştürün.</p>\n<p>Dönüştürülen PNG'yi paylaşın. Alıcının telefonu ya da programı ne olursa olsun, dosya açılır.</p>\n<h2 id=\"batch-for-project\">Bir proje için toplu dönüştürmek</h2>\n<p>Proje klasöründeki tüm WebP'leri tek seferde dönüştürün. Dosya adları korunur; düzen bozulmaz.</p>\n<p>Dönüştürülenleri ayrı bir klasöre koyun. Orijinaller ve dönüştürülenler karışmamalıdır.</p>\n<p>Projeyi teslim etmeden önce tüm dosyaları açıp kontrol edin. Saydamlık, boyut ve adlandırmayı doğrulayın.</p>\n<h2 id=\"webp-for-school-project\">Okul projesi için WebP dönüştürmek</h2>\n<p>Okul projelerinde PNG kullanın. Öğretmenin bilgisayarı eski olabilir; PNG her makinede açılır.</p>\n<p>Projeyi USB belleğe kopyalamadan önce görselleri PNG'ye çevirin. Sınıf bilgisayarında sürpriz yaşanmaz.</p>\n<p>Dosya adlarını anlaşılır tutun. Öğretmen, dosyanın ne olduğunu adından anlamalıdır.</p>\n<p>Adım adım ilerleyin ve her dosyayı indirmeden önce kontrol edin. Kılavuzun tamamı için <a href=\"/tr/blog/webp-png-ye-donustur-rehberi\">WebP'den PNG'ye kılavuzuna</a> bakın; düzenleme ve uyumluluk ayrıntıları <a href=\"/tr/blog/webp-png-ye-duzenleme-uyumluluk\">WebP'den PNG'ye düzenleme ve uyumluluk</a> yazısındadır. Ters yön için <a href=\"/tr/webp-jpg-ye-donustur\">WebP'den JPG'ye dönüştürücü</a> ve <a href=\"/tr/jpg-webp-ye-donustur\">JPG'den WebP'ye dönüştürücü</a> hazırdır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Saydamlığın dönüştürmeden sağ çıktığını nasıl doğrularım?","answer":"Önizlemede saydam alanlar damalı desenle gösterilir; logonun köşelerinin temiz kaldığını kontrol edin. Karşılaştırma görünümüyle orijinal WebP ile PNG'yi yan yana inceleyin. Beyaz hale görürseniz kaynak WebP'nin gerçekten saydam olduğundan emin olun."},{"question":"WebP ekran görüntülerini kalite kaybı olmadan PNG'ye dönüştürebilir miyim?","answer":"Evet. Dönüştürmenin kendisi kayıpsızdır; WebP'deki pikseller PNG'ye birebir aktarılır. Kaynak WebP zaten kayıplıysa o kayıp geri gelmez ama ek kayıp da yaşanmaz. Sonuç, kaynakla piksel piksel aynıdır."},{"question":"Dönüştürülebilecek tek bir WebP dosyası ne kadar büyük olabilir?","answer":"Araç 20 MB'a kadar dosyaları kabul eder. Çoğu WebP bu sınırın çok altındadır. Daha büyük bir dosyayla karşılaşırsanız önce boyutunu küçültün ya da sıkıştırın."},{"question":"Uzantısı olmayan bir WebP dosyası dönüştürülebilir mi?","answer":"Evet, dosya adının sonuna .webp eklemeniz yeterlidir. Araç formatı uzantıdan tanır. Uzantıyı ekledikten sonra dosyayı normal biçimde yükleyip dönüştürebilirsiniz."},{"question":"WebP'den PNG'ye dönüştürme telefonlarda çalışır mı?","answer":"Evet, modern mobil tarayıcılar aracı tam olarak destekler. Telefonda dosya seçip dönüştürebilir ve sonucu indirebilirsiniz. İndirilen dosyalar genellikle İndirilenler klasörüne gider."},{"question":"WebP'den PNG'ye yerine WebP'den JPG'ye ne zaman seçmeliyim?","answer":"Saydamlık gerekiyorsa PNG'yi seçin; JPG saydamlığı desteklemez. Saydamlık gerekmiyor ve dosya boyutu önemliyse JPG'yi seçin; JPG, PNG'den çok daha küçüktür. Düzenleme ve uyumluluk için PNG, paylaşım ve boyut için JPG önde gider."}];
